def backfill_order_numbers_and_history(apps, schema_editor):
    CustomerOrder = apps.get_model("seasonops", "CustomerOrder")
    StatusHistory = apps.get_model("seasonops", "CustomerOrderStatusHistory")
    for order in CustomerOrder.objects.order_by("pk").iterator():
        if not order.order_number:
            order.order_number = f"SC-{order.created_at.year}-{order.pk:06d}"
            order.save(update_fields=["order_number"])
        StatusHistory.objects.create(
            order_id=order.pk,
            previous_status="",
            status=order.status,
            note="Status at migration.",
            changed_by_id=order.created_by_id,
        )


def preserve_legacy_transfer_balances(apps, schema_editor):
    StockTransfer = apps.get_model("seasonops", "StockTransfer")
    StockTransfer.objects.all().update(legacy_source_deducted=True)
    StockTransfer.objects.filter(status="received").update(
        received_quantity=models.F("quantity"),
    )


